import pandas as pd, json, html, math, os, textwrap
from collections import Counter, defaultdict

DATA='/app/benchmark/data.csv'
OUT='/app/output/final_report.html'
os.makedirs('/app/output', exist_ok=True)
df=pd.read_csv(DATA).sort_values('Year')

def split_composers(s):
    return [x.strip() for x in str(s).split(',')]

def decade_label(y):
    return f"{(int(y)//10)*10}s"

def era(y):
    y=int(y)
    if y <= 1959:
        return 'Golden Age'
    if y <= 1979:
        return 'Silver Age'
    if y <= 1999:
        return 'Modern Expansion'
    return 'Contemporary Era'

def era_range(e):
    return {
        'Golden Age':'1934–1959',
        'Silver Age':'1960–1979',
        'Modern Expansion':'1980–1999',
        'Contemporary Era':'2000–2026'
    }[e]

df['Decade']=df.Year.map(decade_label)
df['Era']=df.Year.map(era)
expanded=[]
for _,r in df.iterrows():
    for c in split_composers(r.Composer):
        expanded.append({'Year':int(r.Year),'Film':r.Film,'Composer':c,'ComposerCredit':r.Composer,'Decade':r.Decade,'Era':r.Era})
ex=pd.DataFrame(expanded)

composer_counts=ex.Composer.value_counts()
total_ceremonies=len(df)
unique_films=df.Film.nunique()
unique_composers=ex.Composer.nunique()
max_wins=int(composer_counts.max())
max_winners=list(composer_counts[composer_counts==max_wins].index)

seen=set(); repeat_rows=[]
for _,r in df.iterrows():
    comps=split_composers(r.Composer)
    repeated=any(c in seen for c in comps)
    repeat_rows.append(repeated)
    seen.update(comps)
repeat_ceremonies=sum(repeat_rows)
repeat_rate=repeat_ceremonies/total_ceremonies

