    for _,r in grp.iterrows():
        comps=split_composers(r.Composer)
        comps_all.extend(comps)
        if any(c in seen_prior for c in comps):
            repeat_count += 1
        if all(c not in seen_prior for c in comps):
            first_timer_count += 1
        seen_prior.update(comps)
    dec_stats.append({
        'decade':dec,
        'ceremonies':len(grp),
        'unique':len(set(comps_all)),
        'credits':len(comps_all),
        'repeat':repeat_count,
        'first_timer_ceremonies':first_timer_count,
        'repeat_rate':repeat_count/len(grp),
        'films':list(grp.Film),
