        seen_e.update(comps)
    era_stats.append({
        'era':e, 'range':era_range(e), 'ceremonies':len(dfg), 'unique':exg.Composer.nunique(),
        'top':vc.head(5).to_dict(), 'repeat_within':repeat_e, 'sample_films':list(dfg.Film.head(3))
    })

