            s.append(f'<text x="{cx+barw/2+2:.1f}" y="{mt+ph-rh-8:.1f}" text-anchor="middle" fill="#9f6b08" font-size="12" font-family="{FONT}" font-weight="700">{d["repeat"]}</text>')
