def timeline_svg():
    # show individual win credits as vertical markers with repeat winners highlighted
    w,h=980,230
    ml,mr,mt,mb=55,45,35,45
    pw=w-ml-mr
    miny,maxyear=int(df.Year.min()),int(df.Year.max())
    s=[f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="Timeline of winning ceremonies with repeat winners highlighted">']
    s.append(f'<rect width="{w}" height="{h}" rx="18" fill="#ffffff"/>')
    s.append(f'<line x1="{ml}" y1="{h/2:.1f}" x2="{w-mr}" y2="{h/2:.1f}" stroke="#cfd8e3" stroke-width="3"/>')
    seen=set()
    for _,r in df.iterrows():
        x=ml+(int(r.Year)-miny)*pw/(maxyear-miny)
        comps=split_composers(r.Composer)
        repeated=any(c in seen for c in comps)
        shared=len(comps)>1
        color='#d7a94b' if repeated else '#244b6b'
        rad=5.5 if repeated else 4
        y=h/2
        s.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{rad}" fill="{color}" opacity="0.92"/>')
        if shared:
            s.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{rad+3}" fill="none" stroke="#7f8ea3" stroke-width="1.4" opacity=".85"/>')
        seen.update(comps)
    for yr in range(1940,2030,10):
        if yr<miny or yr>maxyear: continue
        x=ml+(yr-miny)*pw/(maxyear-miny)
        s.append(f'<line x1="{x:.1f}" y1="{h/2+14:.1f}" x2="{x:.1f}" y2="{h/2+24:.1f}" stroke="#98a2b3"/>')
        s.append(f'<text x="{x:.1f}" y="{h/2+43:.1f}" text-anchor="middle" fill="#667085" font-size="12" font-family="{FONT}">{yr}</text>')
